import { useState, useEffect } from "react";
import { Routes, Route } from "react-router-dom";
import Login from "./components/Login";
import Menu from "./components/Menu";
import ListaIncidencias from "./components/ListaIncidencias";
import Form from "./components/Form";
import UserRoleManagement from "./components/UserRoleManagement";
import API_URL from "./api";

const LOGIN_API_URL = `${API_URL}/login`;

function App() {
  const [usuarioLogueado, setUsuarioLogueado] = useState(null);
  const [incidencias, setIncidencias] = useState([]);
  const [usuarios, setUsuarios] = useState([]);

  const cargarIncidencias = async () => {
    try {
      const res = await fetch(`${API_URL}/incidencias`);
      if (!res.ok) {
        throw new Error(`Error al cargar incidencias: ${res.status} ${res.statusText}`);
      }
      const data = await res.json();
      setIncidencias(data);
    } catch (error) {
      console.error(error);
      alert("No se pudo cargar las incidencias. Asegúrate de que el servidor API esté ejecutándose en localhost:3000.");
    }
  };

  const cargarUsuarios = async () => {
    try {
      const res = await fetch(`${API_URL}/users`);
      if (!res.ok) {
        throw new Error(`Error al cargar usuarios: ${res.status} ${res.statusText}`);
      }
      const data = await res.json();
      setUsuarios(data);
    } catch (error) {
      console.error(error);
      alert("No se pudo cargar los usuarios. Asegúrate de que el servidor API esté ejecutándose en localhost:3000.");
    }
  };

  useEffect(() => {
    cargarIncidencias();
  }, []);

  useEffect(() => {
    cargarUsuarios();
  }, []);

  // LOGIN
  const onLogin = async (email, password) => {
    try {
      const response = await fetch(LOGIN_API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fallo de autenticación. ${response.status}: ${errorData}`);
      }

      const data = await response.json();
      setUsuarioLogueado(data.user);
      localStorage.setItem("usuarioLogueado", JSON.stringify(data.user));
    } catch (error) {
      console.error(error);
      alert(error.message || "Error de conexión al servidor de autenticación.");
    }
  };

  // POST INCIDENCIA (UT05)
  const agregarIncidencia = async (nueva) => {
    // 1. Validar usuario
    const usuarioEncontrado = usuarios.find(
      (u) => u.email === nueva.email
    );

    if (!usuarioEncontrado) {
      alert("Usuario no encontrado. Por favor, regístrese primero.");
      return;
    }

    // 2. Crear objeto final
    const nuevaIncidencia = {
      titulo: nueva.titulo,
      descripcion: nueva.descripcion,
      categoria: nueva.categoria,
      urgencia: nueva.urgencia,
      ubicacion: nueva.ubicacion,
      usuario: usuarioEncontrado,
      estado: "Abierta",
      comentarios: [],
      fecha_registro: new Date().toISOString().split("T")[0],
    };

    // 3. POST
    const response = await fetch(`${API_URL}/incidencias`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(nuevaIncidencia),
    });

    if (response.ok) {
      const creada = await response.json();
      setIncidencias([...incidencias, creada]);
    }
  };

return (
  <div className="container mt-4">

    {!usuarioLogueado ? (
      <div className="row justify-content-center">
        <div className="col-md-4">
          <Login onLogin={onLogin} />
        </div>
      </div>
    ) : (
      <>
        <Menu usuarioLogueado={usuarioLogueado} setUsuarioLogueado={setUsuarioLogueado} />

      <Routes>
        <Route path="/" element={<h2>Bienvenido a la gestión de incidencias</h2>} />
        <Route path="/login" element={<Login setUsuarioLogueado={setUsuarioLogueado} />} />
        <Route path="/incidencias" element={<ListaIncidencias usuario={usuarioLogueado} />} />
        <Route path="/registrar" element={<Form />} />
        <Route path="/usuarios" element={<UserRoleManagement />} />
      </Routes>
        <div className="row">
          {/* LISTADO IZQUIERDA */}
          <div className="col-md-8 mb-4">
            <ListaIncidencias incidencias={incidencias} />
          </div>

          {/* FORMULARIO DERECHA */}
          <div className="col-md-4 mb-4">
            <Form agregarIncidencia={agregarIncidencia} />
          </div>
        </div>

        {/* BOTÓN CERRAR SESIÓN ABAJO A LA DERECHA */}
        <div className="d-flex justify-content-end mb-4">
          <button
            className="btn btn-danger btn-lg px-4"
            onClick={() => {
              setUsuarioLogueado(null);
              localStorage.removeItem("usuarioLogueado");
            }}
          >
            Cerrar sesión
          </button>
        </div>
      </>
    )}

  </div>
);


}

export default App;
